using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using ModelContextProtocol;

var builder = Host.CreateApplicationBuilder(args);

builder.Services.AddHttpClient("WeatherApi", client =>
{
    client.BaseAddress = new Uri("https://api.weather.example.com/");
    client.DefaultRequestHeaders.Add("Accept", "application/json");
});

builder.Services
    .AddMcpServer()
    .WithStdioServerTransport()
    .WithToolsFromAssembly();

await builder.Build().RunAsync();

using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json.Serialization;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class WeatherTools
{
    [McpServerTool, Description("Get the current weather forecast for a city.")]
    public static async Task<string> GetForecast(
        IHttpClientFactory httpClientFactory,
        [Description("The city name to get weather for")] string city,
        [Description("Temperature unit: celsius or fahrenheit")] string unit = "celsius")
    {
        using var client = httpClientFactory.CreateClient("WeatherApi");

        var response = await client.GetAsync($"forecast?city={Uri.EscapeDataString(city)}&unit={unit}");
        response.EnsureSuccessStatusCode();

        var forecast = await response.Content.ReadFromJsonAsync<ForecastResponse>();

        return $"{forecast!.City}: {forecast.Temperature}° {forecast.Unit}, {forecast.Condition}";
    }

    [McpServerTool, Description("Get weather alerts for a given region.")]
    public static async Task<string> GetAlerts(
        IHttpClientFactory httpClientFactory,
        [Description("Region code (e.g., US-CA, EU-DE)")] string region)
    {
        using var client = httpClientFactory.CreateClient("WeatherApi");

        var alerts = await client.GetFromJsonAsync<AlertResponse[]>($"alerts?region={Uri.EscapeDataString(region)}");

        if (alerts is null || alerts.Length == 0)
            return $"No active alerts for {region}.";

        return string.Join("\n", alerts.Select(a => $"[{a.Severity}] {a.Title}: {a.Description}"));
    }
}

public record ForecastResponse(
    [property: JsonPropertyName("city")] string City,
    [property: JsonPropertyName("temperature")] double Temperature,
    [property: JsonPropertyName("unit")] string Unit,
    [property: JsonPropertyName("condition")] string Condition);

public record AlertResponse(
    [property: JsonPropertyName("severity")] string Severity,
    [property: JsonPropertyName("title")] string Title,
    [property: JsonPropertyName("description")] string Description);

